<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute, RouterLink } from 'vue-router'
import { ArrowLeft, CheckCircle2, Clock3, Trophy, Users } from 'lucide-vue-next'
import StaffNote from '../components/StaffNote.vue'
import { requireSupabase, isSupabaseConfigured } from '../services/supabase'
type Session={id:string;title:string;code:string;mode:'self_paced'|'live';status:string;current_question_index:number}
type Question={id:string;position:number;category:string;prompt:string;options:string[];midi:number|null}
const route=useRoute(),code=ref(String(route.params.code||route.query.code||'').trim().toUpperCase()),nickname=ref('')
const session=ref<Session|null>(null),participantId=ref(''),questions=ref<Question[]>([]),index=ref(0),selected=ref('')
const answered=ref(false),score=ref(0),done=ref(false),busy=ref(false),error=ref(''),started=ref(false),answeredLive=ref(false)
const waiting=computed(()=>session.value?.mode==='live'&&session.value.status==='lobby')
const current=computed(()=>session.value?.mode==='live'?questions.value[session.value.current_question_index]:questions.value[index.value])
let channel:any=null
async function join(){busy.value=true;error.value='';try{const db=requireSupabase();const {data:auth}=await db.auth.getSession();if(!auth.session){const {error:e}=await db.auth.signInAnonymously();if(e)throw e}
 const {data,error:e}=await db.rpc('join_class_session',{p_code:code.value.trim().toUpperCase(),p_nickname:nickname.value.trim()});if(e)throw e
 const joined=data as {session:Session;participant_id:string;score:number};session.value=joined.session;participantId.value=joined.participant_id;score.value=joined.score
 const {data:qs,error:qe}=await db.from('session_questions').select('id,position,category,prompt,options,midi').eq('session_id',joined.session.id).order('position');if(qe)throw qe
 questions.value=qs as Question[];started.value=true;subscribe()
 }catch(e){error.value=e instanceof Error?e.message:'No se pudo ingresar a la sesión.'}finally{busy.value=false}}
function subscribe(){if(!session.value)return;const db=requireSupabase();channel=db.channel('student-'+session.value.id).on('postgres_changes',{event:'UPDATE',schema:'public',table:'sessions',filter:'id=eq.'+session.value.id},p=>{session.value={...session.value!,...p.new as Partial<Session>}}).on('postgres_changes',{event:'*',schema:'public',table:'participants',filter:'id=eq.'+participantId.value},p=>{const v=p.new as {score?:number;finished_at?:string};if(v.score!==undefined)score.value=v.score;if(v.finished_at)done.value=true}).subscribe()}
async function answer(){if(!current.value||!selected.value||!session.value)return;busy.value=true;error.value='';try{const db=requireSupabase();const {error:e}=await db.rpc('submit_class_answer',{p_session_id:session.value.id,p_question_id:current.value.id,p_answer:selected.value});if(e)throw e;answered.value=true;if(session.value.mode==='live')answeredLive.value=true}catch(e){error.value=e instanceof Error?e.message:'No se pudo guardar la respuesta.'}finally{busy.value=false}}
async function continueSelfPaced(){if(!session.value)return;if(index.value>=questions.value.length-1){const {error:e}=await requireSupabase().rpc('finish_self_paced_session',{p_session_id:session.value.id});if(e){error.value=e.message;return}done.value=true;return}index.value++;selected.value='';answered.value=false}
watch(()=>session.value?.current_question_index,()=>{if(session.value?.mode==='live'){selected.value='';answered.value=false;answeredLive.value=false}})
onMounted(()=>{if(route.params.code)code.value=String(route.params.code).toUpperCase()})
onUnmounted(()=>{if(channel)requireSupabase().removeChannel(channel)})
</script>
<template>
<div class="page">
 <div class="mb-6 flex items-center gap-3"><RouterLink to="/" class="secondary"><ArrowLeft :size="17"/></RouterLink><div><p class="eyebrow">Participar en una sesión</p><h1 class="text-2xl font-black sm:text-3xl">Guitar Tutor · Aula</h1></div></div>
 <section v-if="!isSupabaseConfigured" class="panel p-6"><h2 class="text-xl font-black">Sesiones aún no configuradas</h2><p class="mt-2 text-sm text-[#718078]">El docente debe completar la conexión de Supabase para habilitar el acceso compartido.</p></section>
 <section v-else-if="!started" class="panel mx-auto max-w-lg p-6 sm:p-8"><h2 class="text-xl font-black">Entrar a una sesión</h2><p class="mt-2 text-sm text-[#718078]">Abre el enlace de tu docente o escribe el código manualmente.</p><form class="mt-5 space-y-4" @submit.prevent="join"><div><label class="mb-1 block text-sm font-bold">Código de sesión</label><input v-model="code" required maxlength="12" autocapitalize="characters" class="w-full rounded-xl border border-[#dce6dd] px-4 py-3 uppercase tracking-widest" placeholder="ABC123"/></div><div><label class="mb-1 block text-sm font-bold">Tu nickname</label><input v-model="nickname" required maxlength="24" class="w-full rounded-xl border border-[#dce6dd] px-4 py-3" placeholder="Ej. Guitarrista23"/></div><button class="primary w-full justify-center" :disabled="busy">{{busy?'Ingresando…':'Ingresar a la sesión'}}</button></form><p v-if="error" class="mt-3 rounded-xl bg-[#fff1ed] p-3 text-sm text-[#9b4f3c]">{{error}}</p></section>
 <section v-else-if="session" class="mx-auto max-w-2xl space-y-4">
  <div class="panel flex flex-wrap items-center justify-between gap-3 p-5"><div><p class="eyebrow">{{session.mode==='live'?'Sesión en vivo':'Prueba individual'}}</p><h2 class="mt-1 text-xl font-black">{{session.title}}</h2><p class="mt-1 text-sm text-[#718078]">Participas como {{nickname}}</p></div><div v-if="done||session.status==='finished'" class="rounded-xl bg-[#edf4ee] px-4 py-2 text-center"><Trophy class="mx-auto text-[#398568]"/><b class="text-lg">{{score}}</b><small class="block text-xs text-[#718078]">puntos</small></div></div>
  <div v-if="done||session.status==='finished'" class="panel p-7 text-center"><CheckCircle2 class="mx-auto text-[#398568]" :size="40"/><h2 class="mt-3 text-2xl font-black">¡Sesión finalizada!</h2><p class="mt-2 text-[#718078]">Tu puntuación: <b>{{score}} puntos</b>. Ya puedes cerrar esta página.</p></div>
  <div v-else-if="waiting" class="panel p-8 text-center"><Users class="mx-auto text-[#398568]" :size="38"/><h2 class="mt-3 text-xl font-black">Ya estás dentro</h2><p class="mt-2 text-sm text-[#718078]">Espera a que el docente inicie. La pregunta aparecerá aquí automáticamente.</p></div>
  <div v-else-if="current" class="panel p-5 sm:p-7"><div class="flex items-center justify-between gap-3"><span class="rounded-full bg-[#edf4ee] px-3 py-1.5 text-xs font-bold text-[#34745b]">{{current.category}}</span><span class="text-xs font-bold text-[#718078]">{{session.mode==='live'?`Pregunta ${session.current_question_index+1} de ${questions.length}`:`Pregunta ${index+1} de ${questions.length}`}}</span></div><h2 class="mt-5 text-xl font-black">{{current.prompt}}</h2><div v-if="current.midi !== null" class="mt-5 max-w-sm"><StaffNote :midi="current.midi"/></div><div class="mt-5 grid gap-3 sm:grid-cols-2"><button v-for="(option,i) in current.options" :key="option" :disabled="answered||answeredLive" @click="selected=option" class="rounded-xl border p-4 text-left text-sm font-bold" :class="selected===option?'border-[#28785e] bg-[#eaf4ed] text-[#23664d]':'border-[#e1e9e2] hover:border-[#9bb9a6]'"><span class="mr-2 text-[#829087]">{{String.fromCharCode(65+i)}}.</span>{{option}}</button></div><div v-if="answered" class="mt-5 rounded-xl bg-[#f0f5f0] p-4"><b>Respuesta registrada</b><p class="mt-1 text-sm text-[#718078]">Tu respuesta ha sido guardada. El docente comunicará los resultados al finalizar la sesión.</p></div><p v-if="error" class="mt-3 text-sm text-[#9b4f3c]">{{error}}</p><div class="mt-5 flex justify-end"><button v-if="!answered" class="primary" :disabled="!selected||busy||answeredLive" @click="answer">{{busy?'Guardando…':'Enviar respuesta'}}</button><button v-else-if="session.mode==='self_paced'" class="primary" @click="continueSelfPaced">{{index===questions.length-1?'Finalizar prueba':'Continuar'}}</button><span v-else class="text-sm font-bold text-[#718078]">Respuesta enviada. Espera la siguiente pregunta.</span></div></div>
  <div v-else class="panel p-6 text-center"><Clock3 class="mx-auto text-[#829087]" :size="32"/><p class="mt-2 text-sm text-[#718078]">Esperando la siguiente pregunta del docente…</p></div>
 </section>
</div>
</template>
